// The JS engine against the original Python (test/fixtures/reference.json,
// generated by tools/make_fixtures.py), plus the intentional differences.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { parse, repr, ParseError } from '../public/engine/parse.js';
import { evaluate } from '../public/engine/evaluate.js';
import { constantValue } from '../public/engine/sample.js';
import { summarize, pathMedians, searchLeft } from '../public/engine/stats.js';
import { buildHistogram, histogramText } from '../public/engine/histogram.js';
import { formatClock, formatDuration, formatterFor, pyFixed } from '../public/engine/format.js';
import { cliText } from '../public/engine/report.js';

const ref = JSON.parse(readFileSync(new URL('./fixtures/reference.json', import.meta.url)));

const f64 = (b64) => {
    const buf = Buffer.from(b64, 'base64');
    return new Float64Array(buf.buffer, buf.byteOffset, buf.length / 8);
};

test('parses every reference expression to the same tree', () => {
    for (const c of ref.parse) {
        const { ast, kind } = parse(c.expr);
        assert.equal(repr(ast), c.ast, c.expr);
        assert.equal(kind !== 'number', c.is_time, `${c.expr}: time-ness`);
        if (!c.stochastic) assert.equal(constantValue(ast), c.value, c.expr);
    }
});

test('rejects every expression the Python rejects', () => {
    for (const expr of ref.errors) {
        assert.throws(() => parse(expr), ParseError, JSON.stringify(expr));
    }
});

test('intentional differences from the Python', () => {
    // Whitespace separates tokens; Python reads "5 3" as 53.
    assert.throws(() => parse('5 3'), ParseError);
    // A bare number after h is minutes; Python drops it.
    assert.equal(constantValue(parse('2h30').ast), 150);
    assert.equal(constantValue(parse('1h 30m').ast), 90);
    // Error positions point into the string as typed.
    const err = (() => {
        try {
            parse('10 +  ~ 5');
        } catch (e) {
            return e;
        }
    })();
    assert.equal(err.pos, 6);
    // Small extensions: bare-hour times, leading-dot numbers, zero durations.
    assert.equal(constantValue(parse('5pm').ast), 17 * 60);
    assert.equal(constantValue(parse('12 am').ast), 0);
    assert.equal(constantValue(parse('.5 * 4').ast), 2);
    assert.equal(constantValue(parse('0m').ast), 0);
});

test('result kinds', () => {
    assert.equal(parse('17:30 - 15m~30m').kind, 'time');
    assert.equal(parse('7:15~~7:45 + 5~~15|30~~45').kind, 'time');
    assert.equal(parse('1h + 30m~45m').kind, 'duration');
    assert.equal(parse('240 - 10~20').kind, 'number');
});

test('formats clock times like format_time_result', () => {
    for (const c of ref.format_time) {
        assert.equal(formatClock(c.minutes, { h12: c.h12, seconds: c.seconds }), c.out, JSON.stringify(c));
    }
});

test('formats durations', () => {
    assert.equal(formatDuration(97.5), '1h 37m');
    assert.equal(formatDuration(120), '2h');
    assert.equal(formatDuration(37), '37m');
    assert.equal(formatDuration(0), '0m');
    assert.equal(formatDuration(-15), '-15m');
    assert.equal(formatDuration(97.5, { seconds: true }), '1h 37m 30s');
    assert.equal(formatDuration(1500), '25h');
});

test('pyFixed rounds exact ties half-to-even, like Python', () => {
    assert.equal(pyFixed(0.125, 2), '0.12');
    assert.equal(pyFixed(0.375, 2), '0.38');
    assert.equal(pyFixed(2.5, 0), '2');
    assert.equal(pyFixed(3.5, 0), '4');
    assert.equal(pyFixed(1234567.5, 0, true), '1,234,568');
    assert.equal(pyFixed(-0.001, 2), '-0.00');
    assert.equal(pyFixed(0.1 + 0.2, 1), '0.3');
});

test('histogram and report text match timecalc.py exactly', () => {
    for (const hcase of ref.histograms) {
        const samples = f64(hcase.samples);
        const sorted = samples.slice().sort();
        const stats = summarize(sorted);
        assert.equal(stats.median, hcase.median, `${hcase.expr}: median`);
        const kind = hcase.is_time ? 'time' : 'number';
        const result = { kind, constant: false, ...stats, pathMedians: hcase.path_medians, sorted };

        for (const c of hcase.cases) {
            const name = `${hcase.expr} ${JSON.stringify({ b: c.buckets, g: c.gaps, m: c.paths, h12: c.h12 })}`;
            const medians = c.paths && hcase.path_medians ? hcase.path_medians.map(([m]) => m) : [stats.median];
            const h = buildHistogram(sorted, { bands: c.buckets, collapseGaps: c.gaps, medians });
            assert.equal(histogramText(h, formatterFor(kind, { h12: c.h12, label: true })), c.histogram, name);

            const opts = { h12: c.h12, bands: c.buckets, collapseGaps: c.gaps, perPath: c.paths };
            assert.equal(cliText(result, opts), c.report + '\n' + c.histogram, `${name}: report`);
        }
    }
});

test('distributions match the Python statistically', () => {
    for (const c of ref.percentiles) {
        const r = evaluate(c.expr, { samples: c.n });
        const spread = c.percentiles['95'] - c.percentiles['5'];
        // Compare CDFs rather than quantiles: the median of a bimodal mix sits
        // in a near-empty gap, where a tiny shift in share moves it a lot.
        for (const [p, v] of Object.entries(c.percentiles)) {
            const below = searchLeft(r.sorted, v) / r.n;
            assert.ok(Math.abs(below - p / 100) < 0.005, `${c.expr}: P(x < ${v}) = ${below}, want ${p / 100}`);
        }
        assert.ok(Math.abs(r.mean - c.mean) < 0.01 * spread, `${c.expr} mean`);
        assert.ok(Math.abs(r.std - c.std) < 0.01 * c.std, `${c.expr} std`);
        if (c.path_medians) {
            assert.equal(r.pathMedians.length, c.path_medians.length, `${c.expr} paths`);
            r.pathMedians.forEach(([m, share], i) => {
                assert.ok(Math.abs(m - c.path_medians[i][0]) < 0.01 * spread, `${c.expr} path ${i} median`);
                assert.ok(Math.abs(share - c.path_medians[i][1]) < 0.01, `${c.expr} path ${i} share`);
            });
        }
    }
});

test('same expression, same samples; spacing does not matter', () => {
    const a = evaluate('10~20 + 5~~10', { samples: 1000 });
    const b = evaluate(' 10 ~ 20+5 ~~ 10 ', { samples: 1000 });
    assert.deepEqual(a.sorted, b.sorted);
});

test('evaluate errors', () => {
    assert.throws(() => evaluate('1/0'), /infinite/);
    assert.throws(() => evaluate('10~20 / 0'), /infinite/);
    assert.throws(() => evaluate('(-8)^0.5'), /not a number/);
});

test('constant results', () => {
    const r = evaluate('17:30 - 15m');
    assert.equal(r.constant, true);
    assert.equal(r.value, 1035);
    assert.equal(r.kind, 'time');
});

test('pathMedians groups by path and sorts by median', () => {
    const pm = pathMedians(Float64Array.from([5, 1, 6, 2, 7]), Int32Array.from([1, 0, 1, 0, 1]));
    assert.deepEqual(pm, [[1.5, 0.4], [6, 0.6]]);
});
